    "code": "import { AppSidebar } from \"./dashboard-01-app-sidebar\"\nimport { ChartAreaInteractive } from \"./dashboard-01-chart-area-interactive\"\nimport { DataTable } from \"./dashboard-01-data-table\"\nimport { SectionCards } from \"./dashboard-01-section-cards\"\nimport { SiteHeader } from \"./dashboard-01-site-header\"\nimport {\n  SidebarInset,\n  SidebarProvider,\n} from \"./dashboard-01-sidebar\"\n\nimport data from \"./dashboard-01-data\"\n\nexport default function Dashboard01() {\n  return (\n    <SidebarProvider\n      style={\n        {\n          \"--sidebar-width\": \"calc(var(--spacing) * 72)\",\n          \"--header-height\": \"calc(var(--spacing) * 12)\",\n        } as React.CSSProperties\n      }\n    >\n      <AppSidebar variant=\"inset\" />\n      <SidebarInset>\n        <SiteHeader />\n        <div className=\"flex flex-1 flex-col\">\n          <div className=\"@container/main flex flex-1 flex-col gap-2\">\n            <div className=\"flex flex-col gap-4 py-4 md:gap-6 md:py-6\">\n              <SectionCards />\n              <div className=\"px-4 lg:px-6\">\n                <ChartAreaInteractive />\n              </div>\n              <DataTable data={data} />\n            </div>\n          </div>\n        </div>\n      </SidebarInset>\n    </SidebarProvider>\n  )\n}",
