    "librarySlug": null,
    "code": "\"use client\";\n\nimport React from \"react\";\nimport { cn } from \"@/lib/utils\";\n\n// ─── Types ────────────────────────────────────────────────────────────────────\ninterface ExpandableGalleryProps {\n  images: string[];\n  className?: string;\n}\n\n// ─── Component ────────────────────────────────────────────────────────────────\nexport function ExpandableGallery({ images, className }: ExpandableGalleryProps) {\n  return (\n    <div className={cn(\"flex h-96 w-full gap-2\", className)}>\n      {images.map((image) => (\n        <div\n          key={image}\n          className=\"relative flex h-full flex-1 cursor-pointer overflow-hidden rounded-xl transition-all duration-500 ease-in-out hover:flex-[3]\"\n        >\n          <img\n            className=\"relative h-full w-full object-cover\"\n            src={image}\n            alt={image}\n          />\n        </div>\n      ))}\n    </div>\n  );\n}",
    "demoCode": "import { ExpandableGallery } from \"@/registry/inspira-react/expandable-gallery\";\n\nconst IMAGES = [\n  \"https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=800&q=80\",\n  \"https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800&q=80\",\n  \"https://images.unsplash.com/photo-1426604966848-d7adac402bff?w=800&q=80\",\n  \"https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&q=80\",\n  \"https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?w=800&q=80\",\n];\n\nexport default function ExpandableGalleryDemo() {\n  return (\n    <div className=\"w-full p-8\">\n      <p className=\"mb-4 text-sm text-muted-foreground\">Hover over a panel to expand it</p>\n      <ExpandableGallery images={IMAGES} />\n    </div>\n  );\n}"
