    "code": "\"use client\";\nimport React, { useEffect, useRef, useState } from \"react\";\nimport { motion, useAnimate } from \"motion/react\";\nimport { cn } from \"@/lib/utils\";\n\nconst CURSOR_IMG =\n  \"url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIzMiIgaGVpZ2h0PSIzMiIgdmlld0JveD0iMCAwIDMyIDMyIj4KICA8Y2lyY2xlIGN4PSIxNiIgY3k9IjE2IiByPSIxNSIgc3R5bGU9ImZpbGw6I2ZmZjtzdHJva2U6IzAwMDtzdHJva2Utd2lkdGg6MXB4OyIgLz4KPC9zdmc+'), auto\";\n\ninterface ScratchToRevealProps {\n  className?: string;\n  width: number;\n  height: number;\n  minScratchPercentage?: number;\n  gradientColors?: [string, string, string];\n  onComplete?: () => void;\n  children?: React.ReactNode;\n}\n\nexport function ScratchToReveal({\n  className,\n  width,\n  height,\n  minScratchPercentage = 50,\n  gradientColors = [\"#A97CF8\", \"#F38CB8\", \"#FDCC92\"],\n  onComplete,\n  children,\n}: ScratchToRevealProps) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const isScratchingRef = useRef(false);\n  const isCompleteRef = useRef(false);\n  const [scope, animate] = useAnimate();\n\n  function drawCanvas() {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const ctx = canvas.getContext(\"2d\");\n    if (!ctx) return;\n\n    ctx.fillStyle = \"#ccc\";\n    ctx.fillRect(0, 0, canvas.width, canvas.height);\n\n    const gradient = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);\n    gradient.addColorStop(0, gradientColors[0]);\n    gradient.addColorStop(0.5, gradientColors[1]);\n    gradient.addColorStop(1, gradientColors[2]);\n    ctx.fillStyle = gradient;\n    ctx.fillRect(0, 0, canvas.width, canvas.height);\n  }\n\n  function scratch(clientX: number, clientY: number) {\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const ctx = canvas.getContext(\"2d\");\n    if (!ctx) return;\n\n    const rect = canvas.getBoundingClientRect();\n    const x = clientX - rect.left + 16;\n    const y = clientY - rect.top + 16;\n\n    ctx.globalCompositeOperation = \"destination-out\";\n    ctx.beginPath();\n    ctx.arc(x, y, 30, 0, Math.PI * 2);\n    ctx.fill();\n  }\n\n  function checkCompletion() {\n    if (isCompleteRef.current) return;\n    const canvas = canvasRef.current;\n    if (!canvas) return;\n    const ctx = canvas.getContext(\"2d\");\n    if (!ctx) return;\n\n    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);\n    const pixels = imageData.data;\n    const totalPixels = pixels.length / 4;\n    let clearPixels = 0;\n\n    for (let i = 3; i < pixels.length; i += 4) {\n      if (pixels[i] === 0) clearPixels++;\n    }\n\n    const percentage = (clearPixels / totalPixels) * 100;\n\n    if (percentage >= minScratchPercentage) {\n      isCompleteRef.current = true;\n      ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n      if (scope.current) {\n        animate(scope.current, {\n          scale: 1,\n          rotate: [0, 10, -10, 10, -10, 0],\n        });\n      }\n      onComplete?.();\n    }\n  }\n\n  useEffect(() => {\n    drawCanvas();\n\n    const handleMouseMove = (e: MouseEvent) => {\n      if (!isScratchingRef.current) return;\n      scratch(e.clientX, e.clientY);\n    };\n\n    const handleTouchMove = (e: TouchEvent) => {\n      if (!isScratchingRef.current) return;\n      const touch = e.touches[0];\n      scratch(touch.clientX, touch.clientY);\n    };\n\n    const handleMouseUp = () => {\n      isScratchingRef.current = false;\n      checkCompletion();\n    };\n\n    const handleTouchEnd = () => {\n      isScratchingRef.current = false;\n      checkCompletion();\n    };\n\n    document.addEventListener(\"mousemove\", handleMouseMove);\n    document.addEventListener(\"mouseup\", handleMouseUp);\n    document.addEventListener(\"touchmove\", handleTouchMove);\n    document.addEventListener(\"touchend\", handleTouchEnd);\n    document.addEventListener(\"touchcancel\", handleTouchEnd);\n\n    return () => {\n      document.removeEventListener(\"mousemove\", handleMouseMove);\n      document.removeEventListener(\"mouseup\", handleMouseUp);\n      document.removeEventListener(\"touchmove\", handleTouchMove);\n      document.removeEventListener(\"touchend\", handleTouchEnd);\n      document.removeEventListener(\"touchcancel\", handleTouchEnd);\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  return (\n    <motion.div\n      ref={scope}\n      style={{\n        width: `${width}px`,\n        height: `${height}px`,\n        cursor: CURSOR_IMG,\n      }}\n      initial={{ scale: 1 }}\n      transition={{ duration: 0.5 }}\n      className={cn(\"relative select-none\", className)}\n    >\n      <canvas\n        ref={canvasRef}\n        width={width}\n        height={height}\n        className=\"absolute left-0 top-0\"\n        onMouseDown={() => {\n          isScratchingRef.current = true;\n        }}\n        onTouchStart={() => {\n          isScratchingRef.current = true;\n        }}\n      />\n      {children}\n    </motion.div>\n  );\n}",
    "demoCode": "\"use client\";\nimport { ScratchToReveal } from \"@/registry/inspira-react/scratch-to-reveal\";\n\nexport default function ScratchToRevealDemo() {\n  return (\n    <div className=\"flex items-center justify-center p-8\">\n      <ScratchToReveal\n        width={300}\n        height={200}\n        gradientColors={[\"#A97CF8\", \"#F38CB8\", \"#FDCC92\"]}\n        onComplete={() => console.log(\"Scratch complete!\")}\n      >\n        <div className=\"flex h-full w-full items-center justify-center rounded-lg bg-green-100\">\n          <p className=\"text-2xl font-bold text-green-600\">You win! 🎉</p>\n        </div>\n      </ScratchToReveal>\n    </div>\n  );\n}"
