    "demoCode": "\"use client\";\n\nimport MoltenMetal from \"./molten-metal\";\n\nexport default function MoltenMetalDemo() {\n  return (\n    <div className=\"relative h-[640px] w-full overflow-hidden bg-black\">\n      <MoltenMetal />\n    </div>\n  );\n}"
