    "code": "\"use client\";\n\nimport { useSliderWithInput } from \"@/registry/origin-ui/use-slider-with-input\";\nimport { Input } from \"@/components/ui/input\";\nimport { Label } from \"@/components/ui/label\";\nimport { Slider } from \"@/components/ui/slider\";\n\nexport default function Component() {\n  const minValue = 0;\n  const maxValue = 100;\n  const initialValue = [25];\n\n  const {\n    sliderValue,\n    inputValues,\n    validateAndUpdateValue,\n    handleInputChange,\n    handleSliderChange,\n  } = useSliderWithInput({ initialValue, maxValue, minValue });\n\n  return (\n    <div className=\"*:not-first:mt-3\">\n      <Label>Volume</Label>\n      <div className=\"flex items-center gap-4\">\n        <Slider\n          aria-label=\"Slider with input\"\n          className=\"grow\"\n          max={maxValue}\n          min={minValue}\n          onValueChange={handleSliderChange}\n          value={sliderValue}\n        />\n        <Input\n          aria-label=\"Enter value\"\n          className=\"h-8 w-14 px-2 py-1 text-center tabular-nums\"\n          inputMode=\"decimal\"\n          onBlur={() => validateAndUpdateValue(inputValues[0], 0)}\n          onChange={(e) => handleInputChange(e, 0)}\n          onKeyDown={(e) => {\n            if (e.key === \"Enter\") {\n              validateAndUpdateValue(inputValues[0], 0);\n            }\n          }}\n          type=\"text\"\n          value={inputValues[0]}\n        />\n      </div>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-255\";\n\nexport default function Demo() {\n  return (\n    <div className=\"w-full max-w-sm\">\n      <Cmp />\n    </div>\n  );\n}"
