    "code": "import { CircleAlertIcon } from \"lucide-react\";\n\nimport {\n  AlertDialog,\n  AlertDialogAction,\n  AlertDialogCancel,\n  AlertDialogContent,\n  AlertDialogDescription,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogTitle,\n  AlertDialogTrigger,\n} from \"@/components/ui/alert-dialog\";\nimport { Button } from \"@/components/ui/button\";\n\nexport default function AlertComponent() {\n  return (\n    <AlertDialog>\n      <AlertDialogTrigger asChild>\n        <Button variant=\"outline\">Alert dialog with icon</Button>\n      </AlertDialogTrigger>\n      <AlertDialogContent>\n        <div className=\"flex flex-col gap-2 max-sm:items-center sm:flex-row sm:gap-4\">\n          <div\n            aria-hidden=\"true\"\n            className=\"flex size-9 shrink-0 items-center justify-center rounded-full border\"\n          >\n            <CircleAlertIcon className=\"opacity-80\" size={16} />\n          </div>\n          <AlertDialogHeader>\n            <AlertDialogTitle>Are you sure?</AlertDialogTitle>\n            <AlertDialogDescription>\n              Are you sure you want to delete your account? All your data will\n              be removed.\n            </AlertDialogDescription>\n          </AlertDialogHeader>\n        </div>\n        <AlertDialogFooter>\n          <AlertDialogCancel>Cancel</AlertDialogCancel>\n          <AlertDialogAction>Confirm</AlertDialogAction>\n        </AlertDialogFooter>\n      </AlertDialogContent>\n    </AlertDialog>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-314\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
