    "code": "import {\n  HoverCard,\n  HoverCardContent,\n  HoverCardTrigger,\n} from \"@/components/ui/hover-card\";\n\nexport default function HoverCardDemo() {\n  return (\n    <HoverCard>\n      <div className=\"flex items-center gap-3\">\n        <img\n          alt=\"Avatar\"\n          className=\"shrink-0 rounded-full\"\n          height={40}\n          src=\"/origin/avatar-40-05.jpg\"\n          width={40}\n        />\n        <div className=\"space-y-0.5\">\n          <HoverCardTrigger asChild>\n            <p>\n              <a className=\"font-medium text-sm hover:underline\" href=\"#\">\n                Keith Kennedy\n              </a>\n            </p>\n          </HoverCardTrigger>\n          <p className=\"text-muted-foreground text-xs\">@k.kennedy</p>\n        </div>\n      </div>\n      <HoverCardContent>\n        <div className=\"space-y-3\">\n          <div className=\"flex items-center gap-3\">\n            <img\n              alt=\"Avatar\"\n              className=\"shrink-0 rounded-full\"\n              height={40}\n              src=\"/origin/avatar-40-05.jpg\"\n              width={40}\n            />\n            <div className=\"space-y-0.5\">\n              <p className=\"font-medium text-sm\">Keith Kennedy</p>\n              <p className=\"text-muted-foreground text-xs\">@k.kennedy</p>\n            </div>\n          </div>\n          <p className=\"text-muted-foreground text-sm\">\n            Designer at{\" \"}\n            <strong className=\"font-medium text-foreground\">@coss.com</strong>.\n            Crafting web experiences with Tailwind CSS.\n          </p>\n          <div className=\"flex items-center gap-2\">\n            <div className=\"-space-x-1.5 flex\">\n              <img\n                alt=\"Friend 01\"\n                className=\"rounded-full ring-1 ring-background\"\n                height={20}\n                src=\"/origin/avatar-20-04.jpg\"\n                width={20}\n              />\n              <img\n                alt=\"Friend 02\"\n                className=\"rounded-full ring-1 ring-background\"\n                height={20}\n                src=\"/origin/avatar-20-05.jpg\"\n                width={20}\n              />\n              <img\n                alt=\"Friend 03\"\n                className=\"rounded-full ring-1 ring-background\"\n                height={20}\n                src=\"/origin/avatar-20-06.jpg\"\n                width={20}\n              />\n            </div>\n            <div className=\"text-muted-foreground text-xs\">\n              3 mutual friends\n            </div>\n          </div>\n        </div>\n      </HoverCardContent>\n    </HoverCard>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-364\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
