    "code": "import {\n  ChevronFirstIcon,\n  ChevronLastIcon,\n  ChevronLeftIcon,\n  ChevronRightIcon,\n} from \"lucide-react\";\n\nimport { usePagination } from \"@/registry/origin-ui/use-pagination\";\nimport {\n  Pagination,\n  PaginationContent,\n  PaginationEllipsis,\n  PaginationItem,\n  PaginationLink,\n} from \"@/components/ui/pagination\";\n\ntype PaginationProps = {\n  currentPage: number;\n  totalPages: number;\n  paginationItemsToDisplay?: number;\n};\n\nexport default function Component({\n  currentPage,\n  totalPages,\n  paginationItemsToDisplay = 5,\n}: PaginationProps) {\n  const { pages, showLeftEllipsis, showRightEllipsis } = usePagination({\n    currentPage,\n    paginationItemsToDisplay,\n    totalPages,\n  });\n\n  return (\n    <Pagination>\n      <PaginationContent>\n        {/* First page button */}\n        <PaginationItem>\n          <PaginationLink\n            aria-disabled={currentPage === 1 ? true : undefined}\n            aria-label=\"Go to first page\"\n            className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n            href={currentPage === 1 ? undefined : `#/page/${currentPage - 1}`}\n            role={currentPage === 1 ? \"link\" : undefined}\n          >\n            <ChevronFirstIcon aria-hidden=\"true\" size={16} />\n          </PaginationLink>\n        </PaginationItem>\n\n        {/* Previous page button */}\n        <PaginationItem>\n          <PaginationLink\n            aria-disabled={currentPage === 1 ? true : undefined}\n            aria-label=\"Go to previous page\"\n            className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n            href={currentPage === 1 ? undefined : `#/page/${currentPage - 1}`}\n            role={currentPage === 1 ? \"link\" : undefined}\n          >\n            <ChevronLeftIcon aria-hidden=\"true\" size={16} />\n          </PaginationLink>\n        </PaginationItem>\n\n        {/* Left ellipsis (...) */}\n        {showLeftEllipsis && (\n          <PaginationItem>\n            <PaginationEllipsis />\n          </PaginationItem>\n        )}\n\n        {/* Page number links */}\n        {pages.map((page) => (\n          <PaginationItem key={page}>\n            <PaginationLink\n              href={`#/page/${page}`}\n              isActive={page === currentPage}\n            >\n              {page}\n            </PaginationLink>\n          </PaginationItem>\n        ))}\n\n        {/* Right ellipsis (...) */}\n        {showRightEllipsis && (\n          <PaginationItem>\n            <PaginationEllipsis />\n          </PaginationItem>\n        )}\n\n        {/* Next page button */}\n        <PaginationItem>\n          <PaginationLink\n            aria-disabled={currentPage === totalPages ? true : undefined}\n            aria-label=\"Go to next page\"\n            className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n            href={\n              currentPage === totalPages\n                ? undefined\n                : `#/page/${currentPage + 1}`\n            }\n            role={currentPage === totalPages ? \"link\" : undefined}\n          >\n            <ChevronRightIcon aria-hidden=\"true\" size={16} />\n          </PaginationLink>\n        </PaginationItem>\n\n        {/* Last page button */}\n        <PaginationItem>\n          <PaginationLink\n            aria-disabled={currentPage === totalPages ? true : undefined}\n            aria-label=\"Go to last page\"\n            className=\"aria-disabled:pointer-events-none aria-disabled:opacity-50\"\n            href={\n              currentPage === totalPages ? undefined : `#/page/${totalPages}`\n            }\n            role={currentPage === totalPages ? \"link\" : undefined}\n          >\n            <ChevronLastIcon aria-hidden=\"true\" size={16} />\n          </PaginationLink>\n        </PaginationItem>\n      </PaginationContent>\n    </Pagination>\n  );\n}",
    "demoCode": "\"use client\";\n\nimport { useState } from \"react\";\n\nimport Cmp from \"@/registry/origin-ui/comp-460\";\n\nexport default function Demo() {\n  const [page, setPage] = useState(3);\n  const total = 10;\n  return (\n    <div className=\"w-full max-w-lg\">\n      <Cmp currentPage={page} totalPages={total} paginationItemsToDisplay={5} />\n    </div>\n  );\n}"
