    "library": "Origin UI",
    "librarySlug": "origin-ui",
    "code": "import { SearchIcon } from \"lucide-react\";\nimport { useId } from \"react\";\n\nimport Logo from \"@/registry/origin-ui/logo\";\nimport { Button } from \"@/components/ui/button\";\nimport { Input } from \"@/components/ui/input\";\nimport {\n  NavigationMenu,\n  NavigationMenuItem,\n  NavigationMenuLink,\n  NavigationMenuList,\n} from \"@/components/ui/navigation-menu\";\nimport {\n  Popover,\n  PopoverContent,\n  PopoverTrigger,\n} from \"@/components/ui/popover\";\n\n// Navigation links array to be used in both desktop and mobile menus\nconst navigationLinks = [\n  { href: \"#\", label: \"Products\" },\n  { href: \"#\", label: \"Categories\" },\n  { href: \"#\", label: \"Deals\" },\n];\n\nexport default function Component() {\n  const id = useId();\n\n  return (\n    <header className=\"border-b px-4 md:px-6\">\n      <div className=\"flex h-16 items-center justify-between gap-4\">\n        {/* Left side */}\n        <div className=\"flex flex-1 items-center gap-2\">\n          {/* Mobile menu trigger */}\n          <Popover>\n            <PopoverTrigger asChild>\n              <Button\n                className=\"group size-8 md:hidden\"\n                size=\"icon\"\n                variant=\"ghost\"\n              >\n                <svg\n                  className=\"pointer-events-none\"\n                  fill=\"none\"\n                  height={16}\n                  stroke=\"currentColor\"\n                  strokeLinecap=\"round\"\n                  strokeLinejoin=\"round\"\n                  strokeWidth=\"2\"\n                  viewBox=\"0 0 24 24\"\n                  width={16}\n                  xmlns=\"http://www.w3.org/2000/svg\"\n                >\n                  <path\n                    className=\"-translate-y-[7px] origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-x-0 group-aria-expanded:translate-y-0 group-aria-expanded:rotate-315\"\n                    d=\"M4 12L20 12\"\n                  />\n                  <path\n                    className=\"origin-center transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.8)] group-aria-expanded:rotate-45\"\n                    d=\"M4 12H20\"\n                  />\n                  <path\n                    className=\"origin-center translate-y-[7px] transition-all duration-300 ease-[cubic-bezier(.5,.85,.25,1.1)] group-aria-expanded:translate-y-0 group-aria-expanded:rotate-135\"\n                    d=\"M4 12H20\"\n                  />\n                </svg>\n              </Button>\n            </PopoverTrigger>\n            <PopoverContent align=\"start\" className=\"w-36 p-1 md:hidden\">\n              <NavigationMenu className=\"max-w-none *:w-full\">\n                <NavigationMenuList className=\"flex-col items-start gap-0 md:gap-2\">\n                  {navigationLinks.map((link) => (\n                    <NavigationMenuItem className=\"w-full\" key={link.label}>\n                      <NavigationMenuLink className=\"py-1.5\" href={link.href}>\n                        {link.label}\n                      </NavigationMenuLink>\n                    </NavigationMenuItem>\n                  ))}\n                  <NavigationMenuItem\n                    aria-hidden=\"true\"\n                    className=\"w-full\"\n                    role=\"presentation\"\n                  >\n                    <div\n                      aria-orientation=\"horizontal\"\n                      className=\"-mx-1 my-1 h-px bg-border\"\n                      role=\"separator\"\n                      tabIndex={-1}\n                    />\n                  </NavigationMenuItem>\n                  <NavigationMenuItem className=\"w-full\">\n                    <NavigationMenuLink className=\"py-1.5\" href=\"#\">\n                      Sign In\n                    </NavigationMenuLink>\n                  </NavigationMenuItem>\n                  <NavigationMenuItem className=\"w-full\">\n                    <Button\n                      asChild\n                      className=\"mt-0.5 w-full text-left text-sm\"\n                      size=\"sm\"\n                    >\n                      <span className=\"flex items-baseline gap-2\">\n                        Cart\n                        <span className=\"text-primary-foreground/60 text-xs\">\n                          2\n                        </span>\n                      </span>\n                    </Button>\n                  </NavigationMenuItem>\n                </NavigationMenuList>\n              </NavigationMenu>\n            </PopoverContent>\n          </Popover>\n          {/* Main nav */}\n          <div className=\"flex flex-1 items-center gap-6 max-md:justify-between\">\n            <a className=\"text-primary hover:text-primary/90\" href=\"#\">\n              <Logo />\n            </a>\n            {/* Navigation menu */}\n            <NavigationMenu className=\"max-md:hidden\">\n              <NavigationMenuList className=\"gap-2\">\n                {navigationLinks.map((link) => (\n                  <NavigationMenuItem key={link.label}>\n                    <NavigationMenuLink\n                      className=\"py-1.5 font-medium text-muted-foreground hover:text-primary\"\n                      href={link.href}\n                    >\n                      {link.label}\n                    </NavigationMenuLink>\n                  </NavigationMenuItem>\n                ))}\n              </NavigationMenuList>\n            </NavigationMenu>\n            {/* Search form */}\n            <div className=\"relative\">\n              <Input\n                className=\"peer h-8 ps-8 pe-2\"\n                id={id}\n                placeholder=\"Search...\"\n                type=\"search\"\n              />\n              <div className=\"pointer-events-none absolute inset-y-0 start-0 flex items-center justify-center ps-2 text-muted-foreground/80 peer-disabled:opacity-50\">\n                <SearchIcon size={16} />\n              </div>\n            </div>\n          </div>\n        </div>\n        {/* Right side */}\n        <div className=\"flex items-center gap-2 max-md:hidden\">\n          <Button asChild className=\"text-sm\" size=\"sm\" variant=\"ghost\">\n            <a href=\"#\">Sign In</a>\n          </Button>\n          <Button asChild className=\"text-sm\" size=\"sm\">\n            <a href=\"#\">\n              <span className=\"flex items-baseline gap-2\">\n                Cart\n                <span className=\"text-primary-foreground/60 text-xs\">2</span>\n              </span>\n            </a>\n          </Button>\n        </div>\n      </div>\n    </header>\n  );\n}",
