    "library": "Origin UI",
    "librarySlug": "origin-ui",
    "code": "import { ChevronsUpDown } from \"lucide-react\";\nimport { Select as SelectPrimitive } from \"radix-ui\";\n\nimport Logo from \"@/registry/origin-ui/logo\";\nimport NotificationMenu from \"@/registry/origin-ui/notification-menu\";\nimport UserMenu from \"@/registry/origin-ui/user-menu\";\nimport {\n  Breadcrumb,\n  BreadcrumbEllipsis,\n  BreadcrumbItem,\n  BreadcrumbLink,\n  BreadcrumbList,\n  BreadcrumbSeparator,\n} from \"@/components/ui/breadcrumb\";\nimport { Button } from \"@/components/ui/button\";\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuItem,\n  DropdownMenuTrigger,\n} from \"@/components/ui/dropdown-menu\";\nimport {\n  Select,\n  SelectContent,\n  SelectItem,\n  SelectValue,\n} from \"@/components/ui/select\";\n\nexport default function Component() {\n  return (\n    <header className=\"border-b px-4 md:px-6\">\n      <div className=\"flex h-16 items-center justify-between gap-4\">\n        {/* Left side */}\n        <div className=\"flex items-center gap-2\">\n          <Breadcrumb>\n            <BreadcrumbList>\n              <BreadcrumbItem>\n                <BreadcrumbLink className=\"text-foreground\" href=\"#\">\n                  <Logo />\n                </BreadcrumbLink>\n              </BreadcrumbItem>\n              <BreadcrumbSeparator> / </BreadcrumbSeparator>\n              <BreadcrumbItem className=\"md:hidden\">\n                <DropdownMenu>\n                  <DropdownMenuTrigger className=\"hover:text-foreground\">\n                    <BreadcrumbEllipsis />\n                    <span className=\"sr-only\">Toggle menu</span>\n                  </DropdownMenuTrigger>\n                  <DropdownMenuContent align=\"start\">\n                    <DropdownMenuItem asChild>\n                      <a href=\"#\">Personal Account</a>\n                    </DropdownMenuItem>\n                    <DropdownMenuItem asChild>\n                      <a href=\"#\">Projects</a>\n                    </DropdownMenuItem>\n                  </DropdownMenuContent>\n                </DropdownMenu>\n              </BreadcrumbItem>\n              <BreadcrumbItem className=\"max-md:hidden\">\n                <BreadcrumbLink href=\"#\">Personal Account</BreadcrumbLink>\n              </BreadcrumbItem>\n              <BreadcrumbSeparator className=\"max-md:hidden\">\n                {\" \"}\n                /{\" \"}\n              </BreadcrumbSeparator>\n              <BreadcrumbItem className=\"max-md:hidden\">\n                <BreadcrumbLink href=\"#\">Projects</BreadcrumbLink>\n              </BreadcrumbItem>\n              <BreadcrumbSeparator> / </BreadcrumbSeparator>\n              <BreadcrumbItem>\n                <Select defaultValue=\"1\">\n                  <SelectPrimitive.SelectTrigger\n                    aria-label=\"Select project\"\n                    asChild\n                  >\n                    <Button\n                      className=\"h-8 px-1.5 text-foreground focus-visible:bg-accent focus-visible:ring-0\"\n                      variant=\"ghost\"\n                    >\n                      <SelectValue placeholder=\"Select project\" />\n                      <ChevronsUpDown\n                        className=\"text-muted-foreground/80\"\n                        size={14}\n                      />\n                    </Button>\n                  </SelectPrimitive.SelectTrigger>\n                  <SelectContent className=\"[&_*[role=option]>span]:start-auto [&_*[role=option]>span]:end-2 [&_*[role=option]]:ps-2 [&_*[role=option]]:pe-8\">\n                    <SelectItem value=\"1\">Main project</SelectItem>\n                    <SelectItem value=\"2\">Origin project</SelectItem>\n                  </SelectContent>\n                </Select>\n              </BreadcrumbItem>\n            </BreadcrumbList>\n          </Breadcrumb>\n        </div>\n        {/* Right side */}\n        <div className=\"flex items-center gap-4\">\n          {/* Notification */}\n          <NotificationMenu />\n          {/* User menu */}\n          <UserMenu />\n        </div>\n      </div>\n    </header>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-583\";\n\nexport default function Demo() {\n  return <Cmp />;\n}"
