    "library": "Origin UI",
    "librarySlug": "origin-ui",
    "code": "\"use client\";\n\nimport { ChevronDownIcon } from \"lucide-react\";\nimport { useState } from \"react\";\n\nimport { Button } from \"@/components/ui/button\";\nimport {\n  DropdownMenu,\n  DropdownMenuContent,\n  DropdownMenuRadioGroup,\n  DropdownMenuRadioItem,\n  DropdownMenuTrigger,\n} from \"@/components/ui/dropdown-menu\";\n\nconst options = [\n  {\n    description:\n      \"All commits from this branch will be added to the base branch via a commit version.\",\n    label: \"Merge pull request\",\n  },\n  {\n    description:\n      \"The 6 commits from this branch will be combined into one commit in the base branch.\",\n    label: \"Squash and merge\",\n  },\n  {\n    description:\n      \"The 6 commits from this branch will be rebased and added to the base branch.\",\n    label: \"Rebase and merge\",\n  },\n];\n\nexport default function Component() {\n  const [selectedIndex, setSelectedIndex] = useState(\"0\");\n\n  return (\n    <div className=\"inline-flex divide-x divide-primary-foreground/30 rounded-md shadow-xs rtl:space-x-reverse\">\n      <Button className=\"rounded-none shadow-none first:rounded-s-md last:rounded-e-md focus-visible:z-10\">\n        {options[Number(selectedIndex)].label}\n      </Button>\n      <DropdownMenu>\n        <DropdownMenuTrigger asChild>\n          <Button\n            aria-label=\"Options\"\n            className=\"rounded-none shadow-none first:rounded-s-md last:rounded-e-md focus-visible:z-10\"\n            size=\"icon\"\n          >\n            <ChevronDownIcon aria-hidden=\"true\" size={16} />\n          </Button>\n        </DropdownMenuTrigger>\n        <DropdownMenuContent\n          align=\"end\"\n          className=\"w-72 max-w-xs\"\n          side=\"bottom\"\n          sideOffset={4}\n        >\n          <DropdownMenuRadioGroup\n            onValueChange={setSelectedIndex}\n            value={selectedIndex}\n          >\n            {options.map((option, index) => (\n              <DropdownMenuRadioItem\n                className=\"items-start [&>span]:pt-1.5\"\n                key={option.label}\n                value={String(index)}\n              >\n                <div className=\"flex flex-col gap-1\">\n                  <span className=\"font-medium text-sm\">{option.label}</span>\n                  <span className=\"text-muted-foreground text-xs\">\n                    {option.description}\n                  </span>\n                </div>\n              </DropdownMenuRadioItem>\n            ))}\n          </DropdownMenuRadioGroup>\n        </DropdownMenuContent>\n      </DropdownMenu>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-131\";\n\nexport default function Demo() {\n  return (\n    <div className=\"flex min-h-[460px] w-full items-start justify-center p-10 pt-24\">\n      <div className=\"flex w-full max-w-md items-center justify-between gap-4 rounded-xl border border-border bg-card p-4 text-card-foreground\">\n        <div className=\"min-w-0\">\n          <p className=\"truncate font-medium text-sm\">feat: add usage-based billing</p>\n          <p className=\"text-muted-foreground text-xs\">#482 · 6 commits · checks passed</p>\n        </div>\n        <Cmp />\n      </div>\n    </div>\n  );\n}"
