    "code": "import {\n  Avatar,\n  AvatarFallback,\n  AvatarImage,\n} from \"@/components/ui/avatar\";\n\nexport default function Component() {\n  return (\n    <div className=\"relative\">\n      <Avatar>\n        <AvatarImage alt=\"Kelly King\" src=\"https://i.pravatar.cc/160?img=47\" />\n        <AvatarFallback>KK</AvatarFallback>\n      </Avatar>\n      <span className=\"-end-0.5 -bottom-0.5 absolute size-3 rounded-full border-2 border-background bg-emerald-500\">\n        <span className=\"sr-only\">Online</span>\n      </span>\n    </div>\n  );\n}",
    "demoCode": "import Cmp from \"@/registry/origin-ui/comp-394\";\n\nexport default function Demo() {\n  return (\n    <div className=\"flex flex-col items-center gap-4\">\n      <Cmp />\n      <div className=\"text-center\">\n        <p className=\"font-medium text-foreground\">Kelly King</p>\n        <p className=\"text-sm text-muted-foreground\">Online</p>\n      </div>\n    </div>\n  );\n}"
